import{_ as a,a0 as p,w as u,s as o,ao as l,I as i,x as n,a1 as r,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Linux 黑話解釋：什麼是 Linux 中的 GUI、CLI 和 TUI？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux 黑話解釋：什麼是 Linux 中的 GUI、CLI 和 TUI？ | LCTT (202011) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 黑話解釋：什麼是 Linux 中的 GUI、CLI 和 TUI？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 黑話解釋：什麼是 Linux 中的 GUI、CLI 和 TUI？ | LCTT (202011) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202011/20201103 Linux Jargon Buster- What are GUI, CLI and TUI in Linux","title":"Linux 黑話解釋：什麼是 Linux 中的 GUI、CLI 和 TUI？","tag":"202011","desc":""},"relativePath":"202011/20201103 Linux Jargon Buster- What are GUI, CLI and TUI in Linux.md","filePath":"[post].md"}'),I={name:"202011/20201103 Linux Jargon Buster- What are GUI, CLI and TUI in Linux.md"};function m(f,t,d,L,x,T){const s=p("Link");return u(),o("div",null,[t[34]||(t[34]=l('<h1 id="linux-黑話解釋-什麼是-linux-中的-gui、cli-和-tui" tabindex="-1">Linux 黑話解釋：什麼是 Linux 中的 GUI、CLI 和 TUI？ <a class="header-anchor" href="#linux-黑話解釋-什麼是-linux-中的-gui、cli-和-tui" aria-label="Permalink to “Linux 黑話解釋：什麼是 Linux 中的 GUI、CLI 和 TUI？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202011/10/092051zw3ofb365a63fahl.jpg" alt=""></p><p>當你開始使用 Linux 並關注關於 Linux 的網站和論壇時，你會經常遇到諸如 GUI、CLI 等術語，有時還會遇到 TUI。</p><p>這一章的 Linux 黑話解釋簡要解釋了這些術語，以便你作為一個（新的）Linux 用户在使用這些縮寫詞時能夠更好地理解上下文。</p><p>説實話，像 GUI、CLI 或 TUI 這樣的術語並不是 Linux 的專屬術語。這些都是通用的計算術語，你會發現在非 Linux 的討論中也會用到它們。</p><h3 id="gui-圖形用户界面graphical-user-interface" tabindex="-1">GUI - <ruby>圖形用户界面<rt>Graphical User Interface</rt></ruby> <a class="header-anchor" href="#gui-圖形用户界面graphical-user-interface" aria-label="Permalink to “GUI - 圖形用户界面Graphical User Interface”">​</a></h3><p>這可能是你在這裏最常遇到的詞彙。這是因為我們專注於桌面 Linux 用户，並試圖涵蓋易於使用的圖形化方法和應用程序。</p><p>GUI 應用程序（或圖形應用程序）基本上是指任何可以與你的鼠標、觸摸板或觸摸屏交互的東西。有了圖標和其他視覺概念，你可以使用鼠標指針來訪問功能。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2018/04/gimp-2-10-interface.jpg?resize=800%2C450&amp;ssl=1" alt="GIMP：一個用於照片編輯的GUI應用程序"></p>',9)),i("p",null,[t[1]||(t[1]=n("在 Linux 上，",-1)),r(s,{href:"https://itsfoss.com/what-is-desktop-environment/"},{default:e(()=>[...t[0]||(t[0]=[n("桌面環境",-1)])]),_:1}),t[2]||(t[2]=n("為你提供了與系統交互的圖形界面，然後，你可以使用 GUI 應用程序，如 GIMP，VLC、Firefox、LibreOffice、文件管理器等來完成各種任務。",-1))]),t[35]||(t[35]=l('<p>GUI 使普通用户的計算機使用變得更加容易，否則它將仍然是一個極客專用區。</p><h3 id="cli-命令列界面command-line-interface" tabindex="-1">CLI - <ruby>命令列界面<rt>Command Line Interface</rt></ruby> <a class="header-anchor" href="#cli-命令列界面command-line-interface" aria-label="Permalink to “CLI - 命令列界面Command Line Interface”">​</a></h3><p>CLI 基本上是一個接受輸入來執行某種功能的命令列程序。基本上，任何可以在終端中通過命令使用的應用程序都屬於這一類。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/10/apt-cache-search-names-only.png?resize=759%2C209&amp;ssl=1" alt="apt-cache 是一個 CLI 工具，用於在基於 Debian 的系統上與 APT 緩存交互"></p><p>早期的電腦與操作系統交互沒有鼠標，你必須使用命令與機器互動。</p><p>如果你認為這都算困難，那你應該知道，早期的計算機甚至沒有一個屏幕可以看到正在輸入的東西，他們用實體的紙質打印機看到他們的輸入命令。我從來沒有用過這樣的電腦，也沒有在現實生活中看到過。我用過的最接近的東西是學習期間的單片機套件。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/11/Ken_Thompson_and_Dennis_Ritchie_at_PDP-11.jpg?resize=800%2C641&amp;ssl=1" alt="肯•湯普森和丹尼斯•裏奇在 PDP11 電腦上開發 UNIX 操作系統"></p>',7)),i("p",null,[t[4]||(t[4]=n("現在的 CLI 還有用嗎？當然有。命令總是有它的好處，特別是當你處理操作系統的核心功能和配置時，比如設置防火牆、管理網絡甚至",-1)),r(s,{href:"https://itsfoss.com/package-manager/"},{default:e(()=>[...t[3]||(t[3]=[n("包管理",-1)])]),_:1}),t[5]||(t[5]=n("。",-1))]),t[36]||(t[36]=i("p",null,"你可能會有一個基於 GUI 的應用程序來完成同樣的任務，但命令可以讓你更精細地訪問這些功能。在一些情況下，你會發現 GUI 應用程序也會用命令（在它們的代碼中使用）與操作系統交互。",-1)),t[37]||(t[37]=i("p",null,[i("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/11/handbrake.png?resize=800%2C537&ssl=1",alt:"Handbrake GUI 應用程序在底層使用 FFMPEG CLI 工具"})],-1)),i("p",null,[t[8]||(t[8]=n("許多流行的 GUI 應用程序往往是基於 CLI 工具的。以",-1)),r(s,{href:"https://itsfoss.com/handbrake/"},{default:e(()=>[...t[6]||(t[6]=[n("Handbrake",-1)])]),_:1}),t[9]||(t[9]=n(" 為例。這是一個流行的開源媒體轉換器，它底層使用的是 ",-1)),r(s,{href:"https://itsfoss.com/ffmpeg/"},{default:e(()=>[...t[7]||(t[7]=[n("FFMPEG 命令列",-1)])]),_:1}),t[10]||(t[10]=n("工具。",-1))]),t[38]||(t[38]=l('<p>很明顯，使用命令列工具沒有圖形工具那麼簡單。不要擔心。除非你有特殊需要，否則你應該可以用圖形化的方式使用 Linux 系統。然而，瞭解基本的 Linux 命令會有很大的幫助。</p><h3 id="tui-終端用户界面terminal-user-interface-也稱為基於文本的用户界面text-based-user-interface" tabindex="-1">TUI - <ruby>終端用户界面<rt>Terminal User Interface</rt></ruby>（也稱為<ruby>基於文本的用户界面<rt>Text-based User Interface</rt></ruby>） <a class="header-anchor" href="#tui-終端用户界面terminal-user-interface-也稱為基於文本的用户界面text-based-user-interface" aria-label="Permalink to “TUI - 終端用户界面Terminal User Interface（也稱為基於文本的用户界面Text-based User Interface）”">​</a></h3><p>這是三者中最不常見的名詞。TUI 基本上部分是 GUI，部分是 CLI。糊塗了嗎？讓我為你解釋一下。</p><p>你已經知道，早期的計算機使用 CLI。在實際的 GUI 出現之前，基於文本的用户界面在終端中提供了一種非常基本的圖形交互。你會有更多的視覺效果，也可以使用鼠標和鍵盤與應用程序進行交互。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/10/nnn-file-browser.jpg?resize=800%2C597&amp;ssl=1" alt="終端中的 nnn 文件瀏覽器"></p><p>TUI 是基於文本的用户界面或終端用户界面的縮寫。“基於文本”這個説法主要是因為你在屏幕上有一堆文本，而“終端用户界面”的説法是因為它們只在終端中使用。</p>',6)),i("p",null,[t[13]||(t[13]=n("TUI 的應用雖然不是那麼常見，但你還是有一些的。",-1)),r(s,{href:"https://itsfoss.com/terminal-web-browsers/"},{default:e(()=>[...t[11]||(t[11]=[n("基於終端的 Web 瀏覽器",-1)])]),_:1}),t[14]||(t[14]=n("是 TUI 程序的好例子。",-1)),r(s,{href:"https://itsfoss.com/best-command-line-games-linux/"},{default:e(()=>[...t[12]||(t[12]=[n("基於終端的遊戲",-1)])]),_:1}),t[15]||(t[15]=n("也屬於這一類。",-1))]),t[39]||(t[39]=i("p",null,[i("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2017/07/cmus-interface.png?resize=734%2C436&ssl=1",alt:"CMUS 是基於終端的音樂播放器"})],-1)),i("p",null,[t[17]||(t[17]=n("當你在 ",-1)),r(s,{href:"https://itsfoss.com/install-media-codecs-ubuntu/"},{default:e(()=>[...t[16]||(t[16]=[n("Ubuntu 中安裝多媒體編解碼器",-1)])]),_:1}),t[18]||(t[18]=n("時，你可能會遇到 TUI，你必須接受 EULA 或做出選擇。",-1))]),t[40]||(t[40]=i("p",null,"TUI 應用程序不像 GUI 應用程序那樣用户友好，它們經常會有學習曲線，但它們比命令列工具更容易使用一些。",-1)),t[41]||(t[41]=i("h3",{id:"最後",tabindex:"-1"},[n("最後…… "),i("a",{class:"header-anchor",href:"#最後","aria-label":"Permalink to “最後……”"},"​")],-1)),t[42]||(t[42]=i("p",null,"TUI 應用程序通常也被認為是 CLI 應用程序，因為它們被限制在終端上。在我看來，你是否認為它們與 CLI 不同，這取決於你。",-1)),t[43]||(t[43]=i("p",null,"我希望你喜歡這篇 Linux 黑話解釋。如果你對這個系列的主題有什麼建議，請在評論中告訴我，我將在以後儘量涵蓋它們。",-1)),t[44]||(t[44]=i("hr",null,null,-1)),i("p",null,[t[20]||(t[20]=n("via: ",-1)),r(s,{href:"https://itsfoss.com/gui-cli-tui/"},{default:e(()=>[...t[19]||(t[19]=[n("https://itsfoss.com/gui-cli-tui/",-1)])]),_:1})]),i("p",null,[t[25]||(t[25]=n("作者：",-1)),r(s,{href:"https://itsfoss.com/author/abhishek/"},{default:e(()=>[...t[21]||(t[21]=[n("Abhishek Prakash",-1)])]),_:1}),t[26]||(t[26]=n(" 選題：",-1)),r(s,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[22]||(t[22]=[n("lujun9972",-1)])]),_:1}),t[27]||(t[27]=n(" 譯者：",-1)),r(s,{href:"https://github.com/wxy"},{default:e(()=>[...t[23]||(t[23]=[n("wxy",-1)])]),_:1}),t[28]||(t[28]=n(" 校對：",-1)),r(s,{href:"https://github.com/wxy"},{default:e(()=>[...t[24]||(t[24]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[31]||(t[31]=n("本文由 ",-1)),r(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[29]||(t[29]=[n("LCTT",-1)])]),_:1}),t[32]||(t[32]=n(" 原創編譯，",-1)),r(s,{href:"https://linux.cn/"},{default:e(()=>[...t[30]||(t[30]=[n("Linux中國",-1)])]),_:1}),t[33]||(t[33]=n(" 榮譽推出",-1))])])}const g=a(I,[["render",m]]);export{b as __pageData,g as default};
